	/** 
	 * jumpstart the process by instantiating2 Offer
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		offerId = OfferService.getOfferInstance()
		.createOffer( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		OfferService.getOfferInstance()
				.createOffer( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.offerSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Offer : " + successValue.getOfferId());
							  if (successValue.getOfferId().equals(offerId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfOfferList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Offer test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on offer consumed")
					);
			subscriber.offerSubscribe( offerId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Offer : " + successValue.getOfferId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfOfferList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on offer for offerId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Offer. 
	 */
	protected Offer read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Offer" );

		Offer entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Offer with primary key" );
		msg.append( offerId );
		
		OfferFetchOneSummary fetchOneSummary = new OfferFetchOneSummary( offerId );

		try {
			entity = OfferService.getOfferInstance().getOffer( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Offer " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Offer.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Offer." );

		StringBuilder msg = new StringBuilder( "Failed to update a Offer : " );        
		Offer entity = read();
		UpdateOfferCommand command = generateUpdateCommand();
		command.setOfferId(entity.getOfferId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Offer." );

			// for use later on...
			offerId = entity.getOfferId();

			OfferService proxy = OfferService.getOfferInstance();  

			proxy.updateOffer( command ).get();

			LOGGER.info( "-- Successfully saved Offer - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + offerId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Offer.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Offer." );

		Offer entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Offer with id " + offerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Offer with id " + offerId );

			throw e;
		}

		try{
			OfferService.getOfferInstance().delete( new DeleteOfferCommand( entity.getOfferId() ) ).get();
			LOGGER.info( "-- Successfully deleted Offer with id " + offerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Offer with id " + offerId );

			throw e;
		}
	}

	/**
	 * get all Offers.
	 */
	protected List<Offer> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Offers:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Offer : " );        
		List<Offer> collection  = new ArrayList<>();

		try {
			// call the static get method on the OfferService
			collection = OfferService.getOfferInstance().getAllOffer();
			assertNotNull( collection, "An Empty collection of Offer was incorrectly returned.");
			
			// Now print out the values
			Offer entity = null;            
			Iterator<Offer> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getOfferId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

